import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Reutilizar y revisar variables de ejecución","description":"","frontmatter":{"title":"Reutilizar y revisar variables de ejecución","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","translationRevision":"2f32598f5eae10c6457f9d34e95c2cce0576c746d8a8fdfd0c1232101c037b08","order":40},"headers":[],"relativePath":"es/user/automations/variables.md","filePath":"es/user/automations/variables.md","lastUpdated":1795727787000}`),s={name:`es/user/automations/variables.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Reutilizar y revisar variables de ejecución <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to “Reutilizar y revisar variables de ejecución”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Cambia una vez un valor compartido y reutilízalo en varias acciones. Necesitas <strong>Automations → Variables</strong> y un host compatible con las operaciones correspondientes. La edición tipada y las operaciones revisadas de Cloud dependen de sus capacidades; guardar localmente no requiere subir datos.</p><h2 id="save-a-local-value" tabindex="-1">Guardar un valor local <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to “Guardar un valor local”">​</a></h2><ol><li>Añade una variable llamada <code>showLabel</code>. Las claves comienzan con letra o guion bajo y admiten letras, números, puntos y guiones, hasta <code>64</code> caracteres. Evita claves repetidas.</li><li>Si está disponible la edición tipada, elige texto e introduce <code>Programa de la tarde</code>. También se admiten número, booleano, lista y secreto. Las listas utilizan un arreglo JSON de cadenas, como <code>[&quot;rojo&quot;, &quot;azul&quot;]</code>.</li><li>Pulsa <strong>Save</strong>. Un conflicto de revisión significa que la colección guardada cambió; vuelve a cargarla y compara con tu modificación prevista.</li><li>Utiliza el valor guardado en un campo de acción compatible con plantillas:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Prueba una acción que solo escriba un registro para inspeccionar el texto. Cambia <code>showLabel</code>, guarda y repite. Las definiciones existentes pueden reutilizar el valor actualizado sin importar de nuevo una plantilla.</li></ol><p>Los <code>params</code> se sustituyen al aplicar una plantilla; los <code>globals</code> se leen durante la ejecución. Una clave ausente produce texto vacío: verifica su escritura antes de usarla como destino o identificador. Las sugerencias del campo ofrecen rutas de evento apropiadas para el disparador.</p><p>Las condiciones también pueden publicar valores por coincidencia. Cuando un filtro declara un alias de captura, el valor que lo satisfizo queda disponible mientras se renderizan las acciones del evento como <code>{{ match.&lt;alias&gt; }}</code> (o <code>{{ match.&lt;posición&gt; }}</code> sin alias). Por ejemplo, una condición «empieza por» sobre el comentario con el alias <code>prefix</code> permite que una acción de registro imprima <code>{{ match.prefix }}</code>. Las capturas son texto plano acotado, solo las producen los filtros y las alternativas que realmente coincidieron, y no cambian las claves de cooldown.</p><p>Pulsa <strong>+</strong> junto a un campo compatible con plantillas para abrir <strong>Insertar variable</strong>: la ruta exacta aparece a la derecha y al elegir una fila se añade <code>{{ ruta }}</code> al campo. Las capturas de este evento también aparecen allí, pero solo se resuelven si su condición coincidió realmente. Asigna un alias a una condición en la sección Condiciones (el botón <strong>Capturar como</strong> del pie muestra los campos de alias) para escribir <code>{{ match.&lt;alias&gt; }}</code>; si no, usa la posición <code>{{ match.&lt;posición&gt; }}</code>.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Revisar cambios de Cloud por separado <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to “Revisar cambios de Cloud por separado”">​</a></h2><p>El control <strong>Changes</strong> de Variables ofrece operaciones nativas revisadas de envío, consulta, aplicación/adopción y retirada cuando el host las admite. Guarda primero la edición local, selecciona una comparación, inspecciona tipo y valor y elige explícitamente la dirección. Consultar una propuesta de Cloud es distinto de aplicarla localmente. Retirar un valor compartido también es distinto de borrar una fila local.</p><p>Los valores secretos o bloqueados se ocultan en las comparaciones y no pueden enviarse mediante esta ruta. No conviertas un secreto en texto ordinario para evitar el bloqueo.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Resultado esperado, estado y recuperación”">​</a></h2><p>Están disponibles las variables locales y el intercambio revisado según capacidades; guardar localmente nunca sube datos automáticamente. Las claves o valores inválidos y las revisiones antiguas bloquean el guardado. Corrige el campo señalado o vuelve a cargar antes de repetir. Para fallos de sesión, consulta <a href="./../cloud/account.html">cuenta de Cloud</a>; para comparaciones, <a href="./../cloud/changes.html">Changes</a>.</p><p>Pruébalo interactivamente antes de tocar tu configuración real:</p>`,16),t(d,{scenario:`automation`,locale:`es`,panel:`automation`,title:`Prueba el espacio de automatizaciones`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>listar todas las claves globales</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>leer un global</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>escribir un global</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>eliminar un global <strong>destructivo</strong></td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};